//==========================================
// QUEUE MODULE (HOA 5, arrays from HOA 2.1)
// A queue is FIFO: the first item enqueued is the first one dequeued.
// Two implementations of the Queue ADT, as in the course:
//   LinkedQueue   - singly linked list with a front and a rear pointer, it never gets full
//   CircularQueue - fixed size array where the end connects back to the start
// dequeue and peek return false (and change nothing) when the queue is empty.
//
// Used in this project by downloads.h (the line of games waiting for a worker thread),
// history.h (the "recently viewed" list is a circular queue), graph.h (breadth first search)
// and genre.h (level order traversal of the genre tree).
//==========================================

//==========================
// LinkedQueue<T>
//==========================
template <typename T>
class LinkedQueue {
private:
    struct Node {
        T value;
        Node* next;
    };
    Node* front;        // next item to leave
    Node* rear;         // last item that arrived
    int count;

//--- LinkedQueue::copyFrom ------------------------------------------------------------------------
// What    : Copies all items of another object, keeping the same order.
// Used by : LinkedQueue::LinkedQueue, LinkedQueue::operator=
//--------------------------------------------------------------------------------------------------
    void copyFrom(const LinkedQueue& other) {
        for (Node* cur = other.front; cur != nullptr; cur = cur->next) enqueue(cur->value);
    }

public:
//--- LinkedQueue::LinkedQueue ---------------------------------------------------------------------
// What    : Creates an empty LinkedQueue.
// Used by : doShowcase (screens.h), genreLevelOrder (genre.h), graphBfsDistances (graph.h),
//           graphShortestPath (graph.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    LinkedQueue() : front(nullptr), rear(nullptr), count(0) {}

//--- LinkedQueue::~LinkedQueue --------------------------------------------------------------------
// What    : Frees all memory of the LinkedQueue (rule of three).
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~LinkedQueue() { clear(); }

//--- LinkedQueue::LinkedQueue ---------------------------------------------------------------------
// What    : Copy constructor: makes a separate copy of all items (part of the rule of three).
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    LinkedQueue(const LinkedQueue& other) : front(nullptr), rear(nullptr), count(0) { copyFrom(other); }

//--- LinkedQueue::operator= -----------------------------------------------------------------------
// What    : Copy assignment: replaces the items with a copy of another LinkedQueue. The `if (this
//           != &other)` check makes x = x safe.
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    LinkedQueue& operator=(const LinkedQueue& other) {
        if (this != &other) {
            clear();
            copyFrom(other);
        }
        return *this;
    }

//--- LinkedQueue::enqueue -------------------------------------------------------------------------
// What    : Adds an item at the rear of the queue.
// Used by : doShowcase (screens.h), DownloadManager::enqueue (downloads.h), genreLevelOrder
//           (genre.h), graphBfsDistances (graph.h), graphShortestPath (graph.h),
//           LinkedQueue::copyFrom, tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void enqueue(const T& value) {
        Node* node = new Node{value, nullptr};
        if (rear == nullptr) front = node;
        else rear->next = node;
        rear = node;
        count++;
    }

//--- LinkedQueue::dequeue -------------------------------------------------------------------------
// What    : Removes the front item and gives it back through the parameter.
// Returns : false when the queue is empty
// Used by : doShowcase (screens.h), DownloadManager::run (downloads.h), genreLevelOrder (genre.h),
//           graphBfsDistances (graph.h), graphShortestPath (graph.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool dequeue(T& out) {
        if (front == nullptr) return false;
        Node* old = front;
        out = old->value;
        front = old->next;
        if (front == nullptr) rear = nullptr;      // the queue became empty
        delete old;
        count--;
        return true;
    }

//--- LinkedQueue::peek ----------------------------------------------------------------------------
// What    : Looks at the front or top item without removing it.
// Returns : false when empty
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    bool peek(T& out) const {
        if (front == nullptr) return false;
        out = front->value;
        return true;
    }

//--- LinkedQueue::empty ---------------------------------------------------------------------------
// What    : Tells if there are no items.
// Returns : true when empty
// Used by : doShowcase (screens.h), DownloadManager::idle (downloads.h), DownloadManager::run
//           (downloads.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool empty() const { return front == nullptr; }
//--- LinkedQueue::size ----------------------------------------------------------------------------
// What    : Number of items.
// Returns : the count
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int size() const { return count; }

//--- LinkedQueue::clear ---------------------------------------------------------------------------
// What    : Removes all items.
// Used by : LinkedQueue::operator=, LinkedQueue::~LinkedQueue
//--------------------------------------------------------------------------------------------------
    void clear() {
        while (front != nullptr) {
            Node* old = front;
            front = front->next;
            delete old;
        }
        rear = nullptr;
        count = 0;
    }
};

//==========================
// CircularQueue<T>
// The array is used like a ring: when front or rear reaches the last place it goes back to place 0.
// The wrap around is "increment, then reset to 0" (no modulo).
//==========================
template <typename T>
class CircularQueue {
private:
    T* data;
    int capacity;
    int front;          // place of the oldest item
    int rear;           // place where the NEXT item will be written
    int count;

//--- CircularQueue::copyFrom ----------------------------------------------------------------------
// What    : Copies all items of another object, keeping the same order.
// Used by : CircularQueue::CircularQueue, CircularQueue::operator=
//--------------------------------------------------------------------------------------------------
    void copyFrom(const CircularQueue& other) {
        for (int i = 0; i < other.count; i++) {
            T value = T();
            other.at(i, value);
            enqueue(value);
        }
    }

public:
//--- CircularQueue::CircularQueue -----------------------------------------------------------------
// What    : Creates an empty CircularQueue with the given capacity or size (a value that is not
//           positive falls back to 8).
// Used by : doShowcase (screens.h), RecentlyViewed::add (history.h), RecentlyViewed::RecentlyViewed
//           (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    explicit CircularQueue(int size = 8)
        : data(nullptr), capacity(size > 0 ? size : 8), front(0), rear(0), count(0) {
        data = new T[capacity];
    }

//--- CircularQueue::~CircularQueue ----------------------------------------------------------------
// What    : Frees all memory of the CircularQueue (rule of three).
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~CircularQueue() { delete[] data; }

//--- CircularQueue::CircularQueue -----------------------------------------------------------------
// What    : Copy constructor: makes a separate copy of all items (part of the rule of three).
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    CircularQueue(const CircularQueue& other)
        : data(nullptr), capacity(other.capacity), front(0), rear(0), count(0) {
        data = new T[capacity];
        copyFrom(other);
    }

//--- CircularQueue::operator= ---------------------------------------------------------------------
// What    : Copy assignment: replaces the items with a copy of another CircularQueue. The `if (this
//           != &other)` check makes x = x safe.
// Used by : RecentlyViewed::add (history.h)
//--------------------------------------------------------------------------------------------------
    CircularQueue& operator=(const CircularQueue& other) {
        if (this != &other) {
            T* fresh = new T[other.capacity];
            delete[] data;
            data = fresh;
            capacity = other.capacity;
            front = 0;
            rear = 0;
            count = 0;
            copyFrom(other);
        }
        return *this;
    }

//--- CircularQueue::full --------------------------------------------------------------------------
// What    : Tells if the ring array has no free place.
// Returns : true when full
// Used by : CircularQueue::enqueue, CircularQueue::enqueueOverwrite
//--------------------------------------------------------------------------------------------------
    bool full() const { return count == capacity; }
//--- CircularQueue::empty -------------------------------------------------------------------------
// What    : Tells if there are no items.
// Returns : true when empty
// Used by : CircularQueue::dequeue, CircularQueue::peek
//--------------------------------------------------------------------------------------------------
    bool empty() const { return count == 0; }
//--- CircularQueue::size --------------------------------------------------------------------------
// What    : Number of items.
// Returns : the count
// Used by : RecentlyViewed::newestFirst (history.h), RecentlyViewed::size (history.h)
//--------------------------------------------------------------------------------------------------
    int size() const { return count; }
//--- CircularQueue::maxSize -----------------------------------------------------------------------
// What    : The capacity of the ring array.
// Returns : the capacity
// Used by : RecentlyViewed::add (history.h)
//--------------------------------------------------------------------------------------------------
    int maxSize() const { return capacity; }

    // adds at the rear. returns false when the queue is full
//--- CircularQueue::enqueue -----------------------------------------------------------------------
// What    : Adds an item at the rear of the queue.
// Used by : CircularQueue::copyFrom, CircularQueue::enqueueOverwrite, RecentlyViewed::add
//           (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool enqueue(const T& value) {
        if (full()) return false;
        data[rear] = value;
        if (++rear == capacity) rear = 0;
        count++;
        return true;
    }

    // adds at the rear, and when the queue is full the OLDEST item is dropped to make room
//--- CircularQueue::enqueueOverwrite --------------------------------------------------------------
// What    : Adds an item at the rear. When the queue is full the oldest item is dropped to make
//           room.
// Used by : doShowcase (screens.h), RecentlyViewed::add (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void enqueueOverwrite(const T& value) {
        if (full()) {
            if (++front == capacity) front = 0;
            count--;
        }
        enqueue(value);
    }

//--- CircularQueue::dequeue -----------------------------------------------------------------------
// What    : Removes the front item and gives it back through the parameter.
// Returns : false when the queue is empty
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool dequeue(T& out) {
        if (empty()) return false;
        out = data[front];
        if (++front == capacity) front = 0;
        count--;
        return true;
    }

//--- CircularQueue::peek --------------------------------------------------------------------------
// What    : Looks at the front or top item without removing it.
// Returns : false when empty
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    bool peek(T& out) const {
        if (empty()) return false;
        out = data[front];
        return true;
    }

    // the item at a position counted from the FRONT (0 = oldest). false when out of range
//--- CircularQueue::at ----------------------------------------------------------------------------
// What    : The item at a position counted from the bottom or the front, without removing it.
// Returns : false when the position is out of range
// Used by : doShowcase (screens.h), RecentlyViewed::add (history.h), RecentlyViewed::newestFirst
//           (history.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool at(int indexFromFront, T& out) const {
        if (indexFromFront < 0 || indexFromFront >= count) return false;
        int place = front + indexFromFront;
        if (place >= capacity) place -= capacity;
        out = data[place];
        return true;
    }

//--- CircularQueue::clear -------------------------------------------------------------------------
// What    : Removes all items.
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    void clear() {
        front = 0;
        rear = 0;
        count = 0;
    }
};

#endif //STEAM_QUEUE_H
